head.script:
// https://inswave01.atlassian.net/browse/WAEA-565



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabs > P > useATagBtn]<br/>웹접근성 향상을 위해 Tab 버튼 영역의 '닫기' 버튼을 a 태그로 렌더링할지 설정합니다.",
    "validation" : [        
        "미설정 시 TabControl 컴포넌트의 useATagBtn 속성이 적용됩니다.",
        "false 설정 시 Tab 버튼 영역의 '닫기' 버튼을 div 태그로 렌더링합니다.",
        "true 설정 시 Tab 버튼 영역의 '닫기' 버튼을 a 태그로 렌더링합니다.",
        "true 설정 시 a 태그의 class 속성에 'w2tabcontrol_tab_close_atag' 클래스가 설정됩니다.",
        "a 태그로 렌더링 시 키보드를 통한 '닫기' 버튼 제어가 가능합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        closable : true,
        alwaysShowCloseBtn : true,
    }

    let propertiesTabs = {
        useATagBtn : con_useATagBtn.getText(),
    }

    let cList = $c.gcm.createCList(properties);
    let cListTabs = $c.gcm.createCList(propertiesTabs);
    let eList = $c.gcm.createEList(["ontabclose"]);

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:tabControl ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:500px;height:200px;">';
    strTarget += '<w2:tabs ' + cListTabs + ' disabled="false" style="height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';
    strTarget += '<w2:tabs ' + cListTabs + ' disabled="false" style="height:40px" id="tabs2" label="Tabs2"></w2:tabs>';
    strTarget += '<w2:tabs ' + cListTabs + ' disabled="false" style="height:40px" id="tabs3" label="Tabs3"></w2:tabs>';
    strTarget += '<w2:content style="height:160px;" id="content1">';
    strTarget += '<w2:button style="width:80px; width:130px; height:50px;" id="content1_child" label="content1_child"></w2:button>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content2">';
    strTarget += '<xf:input id="content2_child" style="width:144px; height:21px; " initValue="content2_child"></xf:input>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content3">';    
    strTarget += '<w2:textbox id="content3_child" label="content3_child" style="width:200px; height:50px; background-color:var(--ws-gray-300);"></w2:textbox>';
    strTarget += '</w2:content>';
    strTarget += '</w2:tabControl>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        grp_comp
    );

    scwin.getTabButtonInfo();
}



scwin.getTabButtonInfo = function () {    
    const tabsId = [
        '[id*=target1_tab_tabs1_close]',
        '[id*=target1_tab_tabs2_close]',
        '[id*=target1_tab_tabs3_close]',
    ]

    tabsId.forEach((tabId, index) => {
        let closeButton = document.querySelector(tabId);
        let closeButtonTagName = closeButton.tagName;
        let closeButtonClassName = closeButton.className;

        wf_body_bottom.getObj("scwin").setReturnValue(`closeButton${index + 1} tagName: ${closeButtonTagName}`);
        wf_body_bottom.getObj("scwin").setReturnValue(`closeButton${index + 1} className: ${closeButtonClassName}`);
    });
}



scwin.target1_ontabclose = function (tabId, index, userTabId) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_ontabclose=====");
}
